    "step2Desc": "Tonda Romana is famed for a thin, crisp base. We work the dough to 55% to 60% hydration — far less than the Neapolitan style — so the crust comes out flat, airy and crackling rather than tall and puffy.",
    "step2CardTitle": "Dough Hydration",
    "step2CardSub": "Low hydration for a crisp rim",
    "step2Spec1Label": "Liquid Proportion",
    "step2Spec1Desc": "55–60% water for a firmer, workable dough",
    "step2Spec2Label": "Water Temperature",
    "step2Spec2Desc": "Friction control during gentle spiral kneading",
    "step2Feat1Name": "Slow spiral kneading",
    "step2Feat1Badge": "20 minutes",
    "step2Feat2Name": "Crumb softness",
    "step2Feat2Badge": "Golden & flat",
    "step2Feat3Name": "Bubble elasticity",
    "step2Feat3Badge": "Flawless",
    "step2Quote": "Water in the dough represents life. More water yields superior softness and fewer carbohydrates per bite.",
