    "step3Sci": "Maturation & enzymatic breakdown",
    "step3Title": "48-Hour Controlled Cold Fermentation at 4°C",
    "step3Desc": "Dough balls rest for exactly 48 hours in a specialized cold room. During this slow maturation, natural enzymes (amylases and proteases) break down complex starches and gluten proteins into simple sugars and amino acids. The dough is naturally \"pre-digested\", ensuring you never experience stomach heaviness after dining.",
    "step3CardTitle": "Maturation",
    "step3CardSub": "Enzymatic aging without rush",
    "step3Spec1Label": "Chamber Temperature",
    "step3Spec1Desc": "Slowed yeast activity for rich flavor development",
    "step3Spec2Label": "Glycemic Impact",
    "step3Spec2Desc": "Complex starches are already broken down",
    "step3Feat1Name": "Lactic acid development",
    "step3Feat1Badge": "Rich aroma",
    "step3Feat2Name": "Zero bloating",
    "step3Feat2Badge": "Effortless digestion",
    "step3Feat3Name": "Natural aeration",
    "step3Feat3Badge": "Alveoli",
    "step3Quote": "Time is the one ingredient you cannot buy or hurry. After 48 hours, dough discovers its soul.",
    "step4Tab": "Tonda Romana Shaping",
    "step4Sci": "Thinly rolled / stretched dough",
    "step4Title": "Tonda Romana Technique: A Flat, Crisp Base",
    "step4Desc": "Tonda Romana means a round, thin-rolled, crisper style. We hand-stretch or lightly roll the dough into a flat disc; the centre stays thin and the rim goldens to a low, even edge — the ideal carrier for rich, classic Neapolitan toppings.",
    "step4CardTitle": "Artisan Handcraft",
    "step4CardSub": "Tonda Romana style",
    "step4Spec1Label": "Center Thickness",
    "step4Spec1Desc": "Thin, flat and crisp base",
    "step4Spec2Label": "Rim Height (Cornicione)",
    "step4Spec2Desc": "Low, golden and even rim, no puffy cornicione",
    "step4Feat1Name": "100% Hand-shaped",
    "step4Feat1Badge": "No machinery",
    "step4Feat2Name": "Flat disc",
    "step4Feat2Badge": "Tonda Romana",
    "step4Feat3Name": "Roman style",
    "step4Feat3Badge": "Tonda Romana",
    "step4Quote": "With your hands you can feel the tension in the dough. A rolling pin would destroy the bubbles that took two days to form.",
    "step5Tab": "375°C Wood Oven",
    "step5Sci": "Even bake & golden crisp rim",
    "step5Title": "375°C Wood Oven: 2 to 3 Minutes of Crisp Bake",
    "step5Desc": "Our domed brick oven reaches 375°C. Tonda Romana bakes longer than a Neapolitan pizza — 2 to 3 minutes — so the crisp base turns golden while the centre stays light. San Marzano keep their fresh acidity, the mozzarella melts nicely, and the rim is flat and crackling.",
