    "step5Spec2Desc": "Resin-free clean flame for an authentic subtle smoke note",
    "step5Feat1Name": "Refractory stone base",
    "step5Feat2Name": "Golden crisp base",
    "step5Feat3Name": "Topping freshness",
    "step5Feat3Badge": "100% juicy",
    "step5Quote": "Two to three minutes at 375 degrees. A crisp base that brings every bite to life."
