    "rev1_author": "Matej K.",
    "rev1_date": "Vor 2 Wochen",
    "rev1_text": "Hervorragende neapolitanische Pizza im wunderschönen Ambiente von Schloss Kodeljevo! Der Teig ist unglaublich leicht und luftig, Zutaten frisch und authentisch italienisch. Auch das Panuozzo ist fantastisch.",
    "rev2_author": "Ana P.",
    "rev2_date": "Vor 1 Monat",
    "rev2_text": "Die beste Pizza in Ljubljana! Das Ambiente auf der Terrasse ist herrlich, das Personal sehr freundlich und die Kruste perfekt. Sehr zu empfehlen: Burrata & Pistazie!",
    "rev3_author": "Luka M.",
    "rev3_date": "Vor 3 Wochen",
    "rev3_text": "Tolles Ambiente unter dem Schloss, super Getränkeauswahl und die besten Panuozzo-Sandwiches in Ljubljana. Pizza und Kaffee 10/10.",
    "rev4_author": "Elena T.",
    "rev4_date": "Vor 1 Monat",
    "rev4_text": "Ein ganz besonderer Ort in Ljubljana. Großartige neapolitanische Pizzen, freundlicher Service und ein herrlicher Sommergarten am Wochenende.",
    "rev5_author": "Jan B.",
    "rev5_date": "Vor 2 Monaten",
    "rev5_text": "Ambiente 10/10, Essen und Pizza fabelhaft. Die Mortadella D.O.P. mit Pistazie auf der Pizza ist eine Spitzenkombination.",
    "rev6_author": "Katarina S.",
    "rev6_date": "Vor 3 Wochen",
    "rev6_text": "Wunderschöne Location, erstklassige handgezogene Pizza und sehr herzliche Bedienung. Wir kommen gerne wieder!",
