    "faqPhotoBadge": "STICKER AUF KAMERA",
    "faqPhotoHighlight": "Keine Kameras auf der Tanzfläche. Lebe den Moment und schütze die Privatsphäre aller.",
    "faqPhotoText": "Kader folgt der Berliner Clubtradition zum Schutz von Privatsphäre und Freiheit auf der Tanzfläche. Am Einlass werden Handykameras mit einem Sticker abgeklebt. Blitzlicht, Videoaufnahmen und Fotografieren im Club sind streng untersagt.",
    "faqDressTitle": "Dresscode",
    "faqDressBadge": "COME AS YOU ARE",
    "faqDressHighlight": "Kommt so, wie ihr euch wohlfühlt. Schwarz, Leder, ausdrucksstark, bequem.",
    "faqDressText": "Wir haben keinen starren Dresscode, schätzen jedoch Individualität, Authentizität und Respekt vor der Clubkultur. Dunkle Kleidung, Leder oder bequeme Club-Outfits sind stets willkommen. Kleidung mit beleidigenden Symbolen ist verboten.",
    "faqAgeTitle": "Altersbeschränkung & Lichtbildausweis (18+)",
    "faqAgeBadge": "STRIKT 18+",
    "faqAgeHighlight": "Einlass ausschließlich für Volljährige mit gültigem physischem Lichtbildausweis.",
    "faqAgeText": "Zutritt zum Club Kader ist ausnahmslos ab 18 Jahren gestattet. Am Einlass muss ein gültiger physischer Lichtbildausweis (Personalausweis oder Reisepass) vorgelegt werden. Fotos auf Smartphones werden nicht akzeptiert.",
