    "faqSaferHighlight": "Null-Toleranz bei Belästigung. Unser Awareness-Team ist die ganze Nacht ansprechbar.",
    "faqSaferText": "Kader verfolgt eine Null-Toleranz-Politik gegenüber Belästigung, Diskriminierung, Homophobie und Gewalt. „Nein heißt Nein.“ Unser geschultes Awareness-Team ist die gesamte Nacht für euch erreichbar.",
