    "faqPaymentHighlight": "Wir akzeptieren Karten, Apple Pay/Google Pay und Bargeld. Bewachte Garderobe vorhanden.",
    "faqPaymentText": "An allen Bars akzeptieren wir kontaktlose Kartenzahlung und Bargeld. Für die Garderobe (2 € pro Stück) empfehlen wir passendes Bargeld oder Karte. Die Garderobe wird durchgehend bewacht.",
