    "faqSoundText": "Kader wird vom legendären vollhorngeladenen 3-Wege-System Klipsch La Scala AL6 angetrieben. Da der Schalldruck auf der Tanzfläche 100 dB(A) überschreitet, liegen an allen Bars kostenlose Ohrstöpsel für euch bereit."
