    "step1Tab": "Caputo Mehl & Hefe",
    "step1Sci": "Kornzusammensetzung & Naturhefe",
    "step1Title": "Rustikales \"00\"-Mehl & Naturhefe",
    "step1Desc": "Die Basis unseres Tonda-Romana-Teigs ist eine rustikale Mischung aus Caputo-Mehl tipo \"00\" (Mulino Caputo) und steingemahlenem Getreide – für eine vollere, körnigere Krume. Wir verwenden frische Hefe und bewusst weniger Wasser, damit der Teig langsam reift und sein typisch knuspriges Wesen entwickelt.",
    "step1CardTitle": "Mehl & Hefe",
    "step1CardSub": "Authentische Kornstruktur aus Neapel",
    "step1Spec1Label": "Mehlstärke (W-Index)",
    "step1Spec1Desc": "Starkes Glutengerüst zum Einschließen der Gärgase",
    "step1Spec2Label": "P/L-Verhältnis",
    "step1Spec2Desc": "Perfekte Balance zwischen Elastizität und Dehnbarkeit",
    "step1Feat1Name": "100% neapolitanische Mahlung",
    "step1Feat2Name": "Sehr geringer Hefegehalt",
    "step1Feat3Name": "Meersalz aus Piran",
    "step1Feat3Badge": "Reines Salz",
    "step1Quote": "Gute Pizza beginnt mit dem Verständnis des Korns. Echtes Mehl lässt den Teig atmen.",
    "step2Tab": "55 % Rustikale Hydration",
    "step2Sci": "Wasserbindung & Krumenstruktur",
    "step2Title": "Rustikaler Teig mit niedriger Hydration",
    "step2Desc": "Tonda Romana ist für ihren dünnen, knusprigen Boden berühmt. Wir arbeiten den Teig auf 55 % bis 60 % Hydration – deutlich weniger als beim neapolitanischen Stil –, sodass der Rand flach, luftig und knackig statt hoch und fluffig wird.",
    "step2CardTitle": "Teighydration",
    "step2CardSub": "Niedrige Hydration für knusprigen Rand",
    "step2Spec1Label": "Flüssigkeitsanteil",
    "step2Spec1Desc": "55–60 % Wasser für einen festeren, bearbeitbaren Teig",
    "step2Spec2Label": "Wassertemperatur",
    "step2Spec2Desc": "Reibungskontrolle beim langsamen Spiralkneten",
    "step2Feat1Name": "Langsames Spiralkneten",
    "step2Feat1Badge": "20 Minuten",
    "step2Feat2Name": "Zartheit der Krume",
    "step2Feat2Badge": "Goldgelb & flach",
    "step2Feat3Name": "Porenelastizität",
    "step2Feat3Badge": "Perfekt",
    "step2Quote": "Wasser im Teig bedeutet Leben. Mehr Wasser sorgt für mehr Weichheit und weniger Kohlenhydrate pro Bissen.",
    "step3Tab": "48h Kaltreifung",
    "step3Sci": "Maturation & enzymatischer Abbau",
    "step3Title": "48-Stündige Kontrollierte Kaltfermentation bei 4°C",
    "step3Desc": "Die Teiglinge ruhen exakt 48 Stunden in einer speziellen Kühlkammer. In dieser Zeit bauen Enzyme (Amylasen und Proteasen) komplexe Stärken und Proteine in einfache Zucker und Aminosäuren um. Der Teig ist auf natürliche Weise „vorverdaut“, sodass kein schweres Völlegefühl entsteht.",
    "step3CardTitle": "Maturation",
    "step3CardSub": "Enzymatische Reifung ohne Eile",
    "step3Spec1Label": "Kammertemperatur",
    "step3Spec1Desc": "Verlangsamte Hefeaktivität für tiefe Geschmacksentwicklung",
    "step3Spec2Label": "Glykämische Wirkung",
    "step3Spec2Desc": "Komplexe Stärken sind bereits aufgeschlossen",
    "step3Feat1Name": "Milchsäureentwicklung",
    "step3Feat1Badge": "Reiches Aroma",
    "step3Feat2Name": "Kein Völlegefühl",
    "step3Feat2Badge": "Leichte Verdauung",
    "step3Feat3Name": "Natürliche Porung",
    "step3Feat3Badge": "Alveolen",
    "step3Quote": "Zeit ist die Zutat, die man weder kaufen noch beschleunigen kann. Nach 48 Stunden erwacht die Seele des Teigs.",
    "step4Tab": "Tonda-Romana-Formgebung",
    "step4Sci": "Dünn ausgerollter / gestreckter Teig",
    "step4Title": "Tonda-Romana-Technik: flacher, knuspriger Boden",
    "step4Desc": "Tonda Romana bedeutet einen runden, dünn ausgerollten, knusprigen Stil. Wir strecken oder rollen den Teig von Hand zu einer flachen Scheibe; die Mitte bleibt dünn, der Rand wird niedrig und golden – ideal für reiche, klassisch neapolitanische Beläge.",
    "step4CardTitle": "Handwerkskunst",
    "step4CardSub": "Tonda-Romana-Stil",
    "step4Spec1Label": "Dicke der Mitte",
    "step4Spec1Desc": "Dünner, flacher und knuspriger Boden",
    "step4Spec2Label": "Randhöhe (Cornicione)",
    "step4Spec2Desc": "Niedriger, goldener, gleichmäßiger Rand ohne fluffiges Cornicione",
    "step4Feat1Name": "100% handgeformt",
    "step4Feat1Badge": "Ohne Maschinen",
    "step4Feat2Name": "Flache Scheibe",
    "step4Feat2Badge": "Tonda Romana",
    "step4Feat3Name": "Römischer Stil",
    "step4Feat3Badge": "Tonda Romana",
    "step4Quote": "Mit den Händen spürt man die Spannung des Teigs. Ein Nudelholz würde die mühsam entstandenen Bläschen zerstören.",
    "step5Tab": "375°C Holzofen",
    "step5Sci": "Gleichmäßiges Backen & goldener, knuspriger Rand",
    "step5Title": "375 °C Holzofen: 2 bis 3 Minuten knusprig",
    "step5Desc": "Unser gemauerter Kuppelofen erreicht 375 °C. Tonda Romana bäckt länger als eine neapolitanische Pizza – 2 bis 3 Minuten –, sodass der knusprige Boden goldgelb wird und die Mitte leicht bleibt. San-Marzano-Tomaten behalten ihre frische Säure, die Mozzarella schmilzt schön und der Rand ist flach und knackig.",
    "step5CardTitle": "Holzbackofen",
    "step5CardSub": "Biscotto-Steinboden & Buchenholzfeuer",
    "step5Spec1Label": "Backzeit",
    "step5Spec1Desc": "Längeres Backen für einen goldgelben, knusprigen Boden",
    "step5Spec2Label": "Brennstoff",
    "step5Spec2Desc": "Harzfreie, saubere Flamme für eine feine Rauchnote",
    "step5Feat1Name": "Schamotte-Bodenplatte",
    "step5Feat2Name": "Goldgelber knuspriger Boden",
    "step5Feat3Name": "Frische des Belags",
    "step5Feat3Badge": "100% saftig",
    "step5Quote": "Zwei bis drei Minuten bei 375 Grad. Ein knuspriger Boden, der jeden Bissen zum Leben erweckt."
