    "rev1_author": "Matej K.",
    "rev1_date": "Il y a 2 semaines",
    "rev1_text": "Excellente pizza napolitaine dans le cadre magnifique du château Kodeljevo ! Pâte exceptionnellement légère et aérée, ingrédients italiens très frais. Le sandwich panuozzo est tout aussi fantastique.",
    "rev2_author": "Ana P.",
    "rev2_date": "Il y a 1 mois",
    "rev2_text": "La meilleure pizza de Ljubljana ! L'ambiance sur la terrasse est magnifique, le personnel très chaleureux et la croûte parfaite. Je recommande vivement Burrata & Pistache !",
    "rev3_author": "Luka M.",
    "rev3_date": "Il y a 3 semaines",
    "rev3_text": "Superbe ambiance au pied du château, grand choix de boissons et les meilleurs panuozzos de Ljubljana. Pizza et café 10/10.",
    "rev4_author": "Elena T.",
    "rev4_date": "Il y a 1 mois",
    "rev4_text": "Un endroit vraiment spécial à Ljubljana. Excellentes pizzas napolitaines, service attentionné et superbe jardin d'été le week-end.",
    "rev5_author": "Jan B.",
    "rev5_date": "Il y a 2 mois",
    "rev5_text": "Ambiance 10/10, plats et pizzas délicieux. L'association mortadelle D.O.P. et pistache est sensationnelle.",
    "rev6_author": "Katarina S.",
    "rev6_date": "Il y a 3 semaines",
    "rev6_text": "Magnifique endroit, pizza artisanale étalée à la main et serveurs très attentionnés. Nous reviendrons avec grand plaisir !",
