    "faqPhotoBadge": "AUTOCOLLANT SUR OBJECTIF",
    "faqPhotoHighlight": "Pas d'appareils sur le dancefloor. Vivez l'instant et préservez l'intimité de chacun.",
    "faqPhotoText": "Le Kader respecte la tradition berlinoise de préservation de l'intimité et de liberté sur la piste de danse. À l'entrée, les objectifs des téléphones sont recouverts d'un autocollant. Tout enregistrement vidéo ou photo est strictement interdit.",
    "faqDressTitle": "Code vestimentaire (Dress code)",
    "faqDressBadge": "COME AS YOU ARE",
    "faqDressHighlight": "Venez comme vous êtes. Noir, cuir, expressif, confortable.",
    "faqDressText": "Nous n'imposons aucun code vestimentaire rigide, mais nous valorisons l'individualité, l'authenticité et le respect de la culture club. Vêtements sombres, cuir ou tenues de danse confortables sont les bienvenus. Tout symbole offensant est prohibé.",
    "faqAgeTitle": "Âge minimum & Pièce d'identité physique (18+)",
    "faqAgeBadge": "STRICTEMENT 18+",
    "faqAgeHighlight": "Entrée strictement réservée aux personnes majeures munies d'une pièce d'identité physique valide.",
    "faqAgeText": "L'accès au club Kader est réservé aux personnes de 18 ans et plus. Vous devez présenter un document d'identité officiel physique avec photo (carte d'identité ou passeport). Les photos sur smartphone ne sont pas acceptées.",
    "faqSaferTitle": "Espaces plus sûrs & Équipe de sensibilisation",
    "faqSaferBadge": "NON C'EST NON · ÉQUIPE SUR PLACE",
    "faqSaferHighlight": "Tolérance zéro envers le harcèlement. Notre équipe de sensibilisation veille toute la nuit.",
    "faqSaferText": "Le Kader applique une politique de tolérance zéro envers tout harcèlement, discrimination, homophobie ou violence. « Non signifie non. » Notre équipe de sensibilisation veille toute la nuit pour votre sécurité.",
