    "faqPaymentBadge": "SANS CONTACT & ESPÈCES",
    "faqPaymentHighlight": "Cartes bancaires, Apple Pay/Google Pay et espèces acceptés. Vestiaire sécurisé disponible.",
    "faqPaymentText": "Tous nos bars acceptent les paiements sans contact par carte et les espèces. Pour le vestiaire (2 € par article), privilégiez l'appoint en espèces ou la carte. Le vestiaire est surveillé toute la nuit.",
