    "faqSoundBadge": "BOUCHONS D'OREILLES GRATUITS",
    "faqSoundHighlight": "Système à pavillon d'exception Klipsch La Scala. Bouchons d'oreilles gratuits à tous les bars.",
    "faqSoundText": "Le Kader est sonorisé par le légendaire système 3 voies à pavillon Klipsch La Scala AL6. La pression acoustique sur la piste dépassant 100 dB(A), des bouchons d'oreilles de qualité supérieure sont offerts à tous les bars."
