    "faqPhotoHighlight": "Niente fotocamere sulla pista. Vivi il momento e proteggi la privacy di tutti.",
    "faqPhotoText": "Il Kader adotta la tradizione dei club berlinesi per proteggere la libertà e la privacy sulla pista. All'ingresso le fotocamere dei telefoni vengono coperte con un adesivo. È severamente vietato fare foto o registrare video all'interno.",
