    "faqDressText": "Non imponiamo un codice rigido, ma celebriamo l'autenticità, l'individualità e il rispetto per la cultura club. Capi scuri, pelle o abbigliamento comodo per ballare sono benvenuti. Sono vietati simboli offensivi o d'odio.",
    "faqAgeTitle": "Limite di età & Documento fisico (18+)",
    "faqAgeBadge": "STRETTAMENTE 18+",
    "faqAgeHighlight": "Ingresso riservato esclusivamente ai maggiorenni con documento di identità originale valido.",
    "faqAgeText": "L'ingresso al club Kader è consentito solo ai maggiori di 18 anni. È obbligatorio mostrare all'ingresso un documento di identità fisico valido con fotografia (carta d'identità o passaporto). Non sono ammesse foto sullo smartphone.",
