    "faqSaferHighlight": "Tolleranza zero contro ogni molestia. Il nostro team di sensibilizzazione è presente tutta la notte.",
    "faqSaferText": "Il Kader applica tolleranza zero contro qualsiasi forma di molestia, discriminazione, omofobia o violenza. \"No significa no.\" La nostra squadra di sensibilizzazione è attiva tutta la notte per offrirti supporto.",
