    "faqPaymentBadge": "CONTACTLESS & CONTANTI",
    "faqPaymentHighlight": "Accettiamo carte, Apple Pay/Google Pay e contanti. Guardaroba custodito disponibile.",
    "faqPaymentText": "Tutti i bar supportano pagamenti rapidi contactless e contanti. Per il guardaroba (2 € a capo) consigliamo contanti o carta. Il guardaroba è custodito per l'intera notte.",
