    "faqSoundText": "Il Kader è dotato del leggendario impianto a 3 vie a tromba Klipsch La Scala AL6. Poiché la pressione sonora supera i 100 dB(A), su ogni bar sono a disposizione tappi per le orecchie gratuiti ad alta fedeltà."
