    "rev1_text": "Vrhunska napolitanska pica u prelepom ambijentu dvorca Kodeljevo! Testo je izuzetno lagano i vazdušasto, a sastojci sveži i italijanski. Panuozzo sendvič je takođe fantastičan.",
