    "rev2_date": "Pre mesec dana",
    "rev2_text": "Najbolja pica u Ljubljani! Ambijent na terasi je divan, osoblje preljubazno, a pice imaju savršenu koricu. Topla preporuka za Buratu i Pistaće!",
    "rev3_author": "Luka M.",
    "rev3_date": "Pre 3 nedelje",
    "rev3_text": "Odličan ambijent pod dvorcem, odličan izbor pića i najbolji panuozzo sendviči u Ljubljani. Pica i kafa čista desetka.",
