    "faqPhotoBadge": "NALEPNICA NA KAMERI",
    "faqPhotoHighlight": "Bez kamera na podijumu za igru. Živi u trenutku i zaštiti privatnost svih prisutnih.",
    "faqPhotoText": "Kader prati strogu berlinsku tradiciju zaštite privatnosti i slobode na plesnom podijumu. Na ulazu osoblje prelepljuje kamere telefona namenskom nalepnicom. Upotreba blica, snimanje videa i fotografisanje u klubu su strogo zabranjeni.",
    "faqDressTitle": "Pravila oblačenja (Dress Code)",
    "faqDressBadge": "COME AS YOU ARE",
    "faqDressHighlight": "Dođite u onome u čemu se osećate najbolje. Crno, koža, izražajno, udobno.",
    "faqDressText": "Kod nas nema krutog protokola, ali cenimo individualnost, autentičnost i poštovanje klupske kulture. Tamna odeća, koža ili udobna odeća za ples su uvek dobrodošli. Strogo je zabranjena odeća sa uvredljivim simbolima.",
    "faqAgeTitle": "Starosna granica & Lični dokument (18+)",
    "faqAgeBadge": "18+ STRIKTNO",
    "faqAgeHighlight": "Ulaz isključivo za punoletne osobe sa važećim fizičkim ličnim dokumentom.",
    "faqAgeText": "Ulaz u noćni klub Kader dozvoljen je isključivo osobama starijim od 18 godina. Na ulazu je obavezno pokazati važeći fizički dokument sa fotografijom (lična karta ili pasoš). Slike dokumenata na telefonu se ne prihvataju.",
    "faqSaferTitle": "Sigurniji prostor & Tim za podršku (Awareness Team)",
    "faqSaferBadge": "NE ZNAČI NE · AWARENESS NA LICU MESTA",
    "faqSaferHighlight": "Nulta tolerancija prema uznemiravanju. Naš tim za podršku prisutan je cele noći.",
    "faqSaferText": "Kader posluje po principu nulte tolerancije prema svakom obliku uznemiravanja, diskriminacije, homofobije ili nasilja. „Ne znači ne.“ Naš tim za podršku prisutan je cele noći za pomoć u svakom trenutku.",
    "faqPaymentTitle": "Plaćanje & Garderoba",
    "faqPaymentBadge": "BEZKONTAKTNO & GOTOVINA",
    "faqPaymentHighlight": "Prihvatamo platne kartice, Apple Pay/Google Pay i gotovinu. Obezbeđena garderoba je dostupna.",
    "faqPaymentText": "Na svim šankovima omogućeno je brzo beskontaktno plaćanje karticama i gotovinom. Za garderobu (2 € po komadu) preporučujemo gotovinu ili karticu. Garderoba je čuvana cele noći.",
    "faqSoundTitle": "Klipsch Ozvučenje & Zaštita sluha",
    "faqSoundBadge": "BESPLATNI ČEPIĆI",
    "faqSoundHighlight": "Vrhunski sistem zvučnika sa hornama Klipsch La Scala. Besplatni čepići za uši na svim šankovima.",
    "faqSoundText": "Kader je opremljen legendarnim trosistemskim ozvučenjem sa hornama Klipsch La Scala AL6. Pošto zvučni pritisak na plesnom podijumu prelazi 100 dB(A), na svim šankovima dostupni su besplatni kvalitetni čepići za uši."
