    "rev1_author": "Matej K.",
    "rev1_date": "2 weken geleden",
    "rev1_text": "Uitstekende Napolitaanse pizza in de prachtige omgeving van Kasteel Kodeljevo! Het deeg is heerlijk luchtig, de ingrediënten vers en Italiaans. Het panuozzo sandwich is ook fantastisch.",
    "rev2_author": "Ana P.",
    "rev2_date": "1 maand geleden",
    "rev2_text": "De beste pizza van Ljubljana! De sfeer op het terras is geweldig, het personeel erg vriendelijk en de korst perfect. Aanrader: Burrata & Pistache!",
    "rev3_author": "Luka M.",
    "rev3_date": "3 weken geleden",
    "rev3_text": "Geweldige sfeer onder het kasteel, uitstekende drankkaart en de lekkerste panuozzo sandwiches van Ljubljana. Pizza en koffie 10/10.",
    "rev4_author": "Elena T.",
    "rev4_date": "1 maand geleden",
    "rev4_text": "Een heel bijzondere plek in Ljubljana. Uitstekende Napolitaanse pizza's, vriendelijke bediening en een heerlijke zomertuin in het weekend.",
    "rev5_author": "Jan B.",
    "rev5_date": "2 maanden geleden",
    "rev5_text": "Sfeer 10/10, eten en pizza formidabel. De combinatie van Mortadella D.O.P. en pistache op pizza is subliem.",
    "rev6_author": "Katarina S.",
    "rev6_date": "3 weken geleden",
    "rev6_text": "Prachtige locatie, eersteklas handgerekte pizza en vriendelijke bediening. We komen graag terug!",
