    "rev1_author": "Matej K.",
    "rev1_date": "2 tygodnie temu",
    "rev1_text": "Wybitna pizza neapolitańska w przepięknej scenerii Zamku Kodeljevo. Puszyste brzegi, doskonały sos San Marzano i świetny personel. Zdecydowanie polecam!",
    "rev2_author": "Ana P.",
    "rev2_date": "miesiąc temu",
    "rev2_text": "Najlepsza pizza w Lublanie! Klimat na tarasie jest cudowny, a kanapka Panuozzo z mortadelą i pistacjami to absolutne mistrzostwo.",
    "rev3_author": "Luka M.",
    "rev3_date": "3 tygodnie temu",
    "rev3_text": "Wspaniały klimat pod zamkiem, doskonały wybór drinków i napojów oraz prawdziwa pizza neapolitańska na najwyższym poziomie. Wrócimy na pewno!",
    "rev4_author": "Elena T.",
    "rev4_date": "miesiąc temu",
    "rev4_text": "Prawdziwie wyjątkowe miejsce w Lublanie. Znakomite ciasto na pizzę, świetna selekcja win i rewelacyjna atmosfera w weekendy.",
    "rev5_author": "Jan B.",
    "rev5_date": "2 miesiące temu",
    "rev5_text": "Atmosfera 10/10, jedzenie i pizza rewelacyjne. Panuozzo Mortadella to poezja smaku. Znakomita obsługa!",
    "rev6_author": "Katarina S.",
    "rev6_date": "3 tygodnie temu",
    "rev6_text": "Piękne miejsce, najwyższej klasy ręcznie rozciągana pizza i bardzo miła obsługa. Pozycja obowiązkowa dla każdego wielbiciela pizzy!",
