    "faqPhotoHighlight": "Zakaz używania aparatów na parkiecie. Żyj chwilą i chroń prywatność innych.",
    "faqPhotoText": "Kader kultywuje berlińską tradycję wolności na parkiecie i dyskrecji. Przy wejściu naklejamy naklejki na aparaty wszystkich telefonów. Fotografowanie i filmowanie w podziemiach klubu jest surowo zabronione.",
