    "faqDressBadge": "BĄDŹ SOBĄ",
    "faqDressHighlight": "Przyjdź tak, jak lubisz. Czerń, skóra, ekspresja, wygoda.",
    "faqDressText": "Nie narzucamy sztywnego dress code'u, lecz cenimy autentyczność, indywidualność i szacunek dla klimatu muzyki undergroundowej. Ubierz się tak, aby swobodnie tańczyć przez całą noc.",
