    "faqAgeHighlight": "Wstęp wyłącznie dla osób pełnoletnich z ważnym fizycznym dokumentem tożsamości.",
    "faqAgeText": "Wstęp do Klubu Nocnego Kader jest dozwolony wyłącznie od 18. roku życia. Przy wejściu należy okazać fizyczny dokument ze zdjęciem (dowód osobisty lub paszport). Zdjęcia dokumentów w telefonie nie są honorowane.",
    "faqSaferTitle": "Bezpieczna Przestrzeń i Zespół Wsparcia (Awareness)",
    "faqSaferBadge": "NIE ZNACZY NIE · ZESPÓŁ AWARENESS NA MIEJSCU",
    "faqSaferHighlight": "Zero tolerancji dla nękania i dyskryminacji. Nasz zespół dba o bezpieczeństwo przez całą noc.",
    "faqSaferText": "Kader stosuje bezwzględną politykę zerowej tolerancji wobec wszelkich przejawów nękania, dyskryminacji, homofobii czy naruszania granic. W razie jakiegokolwiek dyskomfortu zwróć się do zespołu awareness, barmanów lub ochrony.",
    "faqPaymentTitle": "Płatności i Szatnia",
    "faqPaymentBadge": "KARTA I GOTÓWKA",
    "faqPaymentHighlight": "Akceptujemy karty, płatności zbliżeniowe i gotówkę. Monitorowana szatnia dostępna przy wejściu.",
    "faqPaymentText": "Wszystkie bary obsługują szybkie płatności zbliżeniowe (karty, telefon) oraz gotówkę. Dla wygody i bezpieczeństwa zalecamy korzystanie z monitorowanej szatni.",
