    "faqSoundBadge": "DARMOWE ZATYCZKI DO USZU",
    "faqSoundHighlight": "Flagowy tubowy system dźwiękowy Klipsch La Scala. Darmowe zatyczki do uszu dostępne na barze.",
    "faqSoundText": "Sercem klubu Kader jest legendarny trójdrożny system tubowy Klipsch La Scala napędzany wzmacniaczami klasy studyjnej. Dźwięk jest krystalicznie czysty i potężny. Na każdym barze oferujemy darmowe, wysokiej jakości zatyczki do uszu."
