    "step1Desc": "Podstawą naszego ciasta Tonda Romana jest rustykalna mieszanka mąki Mulino Caputo typu \"00\" i mielonych na kamieniu zbóż, dla pełniejszego ziarnistego miękiszu. Używamy świeżych drożdży i umiarkowanej ilości wody, aby ciasto powoli dojrzewało i nabrało typowej chrupiącej struktury.",
