    "step2Title": "Rustykalne Ciasto o Niskiej Hydratacji",
    "step2Desc": "Tonda Romana słynie z cienkiego, chrupiącego spodu. Ciasto wyrabiamy przy 55 %–60 % nawodnienia – znacznie mniej niż w stylu neapolitańskim – dzięki czemu brzeg jest płaski, przewiewny i chrupiący, a nie wysoki i puszysty.",
