    "step2Feat3Name": "Elastyczność pęcherzyków",
    "step2Feat3Badge": "Nienaganna",
    "step2Quote": "Woda w cieście to życie. Więcej wody to większa lekkość i mniej węglowodanów w każdym kęsie.",
    "step3Tab": "48h Dojrzewanie na Zimno",
    "step3Sci": "Dojrzewanie i rozkład enzymatyczny",
    "step3Title": "48-Godzinna Kontrolowana Zimna Fermentacja w 4°C",
    "step3Desc": "Porcje ciasta odpoczywają przez dokładnie 48 godzin w chłodni. Podczas powolnego dojrzewania naturalne enzymy (amylazy i proteazy) rozkładają złożone skrobie i białka glutenu na cukry proste i aminokwasy. Ciasto staje się naturalnie lekkostrawne — po posiłku nigdy nie poczujesz ciężkości w żołądku.",
    "step3CardTitle": "Dojrzewanie",
    "step3CardSub": "Enzymatyczne dojrzewanie bez pośpiechu",
    "step3Spec1Label": "Temperatura Komory",
    "step3Spec1Desc": "Spowolniona praca drożdży dla rozwinięcia bogatego bukietu smaków",
    "step3Spec2Label": "Wpływ Glikemiczny",
    "step3Spec2Desc": "Złożone skrobie są już wstępnie rozłożone",
    "step3Feat1Name": "Rozwój kwasu mlekowego",
    "step3Feat1Badge": "Głęboki aromat",
    "step3Feat2Name": "Zero uczucia ciężkości",
    "step3Feat2Badge": "Lekkie trawienie",
    "step3Feat3Name": "Naturalne napowietrzenie",
    "step3Feat3Badge": "Alveoli",
    "step3Quote": "Czas to jedyny składnik, którego nie można kupić ani przyspieszyć. Po 48 godzinach ciasto odnajduje swoją duszę.",
    "step4Tab": "Formowanie Tonda Romana",
    "step4Sci": "Cienko rozwałkowane / rozciągnięte ciasto",
    "step4Title": "Technika Tonda Romana: płaski, chrupiący spód",
    "step4Desc": "Tonda Romana to okrągły, cienko rozwałkowany i chrupiący styl. Ciasto ręcznie rozciągamy lub lekko rozwałkowujemy w płaski dysk; środek pozostaje cienki, a brzeg staje się niski i złocisty – idealny nośnik dla bogatych, klasycznych neapolitańskich dodatków.",
    "step4CardTitle": "Rzemiosło Ręczne",
    "step4CardSub": "Styl Tonda Romana",
    "step4Spec1Label": "Grubość Środka",
    "step4Spec1Desc": "Cienki, płaski i chrupiący spód",
    "step4Spec2Label": "Wysokość Brzegu (Cornicione)",
    "step4Spec2Desc": "Niski, złocisty, równy brzeg, bez puszystego cornicione",
    "step4Feat1Name": "100% ręcznie formowane",
    "step4Feat1Badge": "Bez użycia maszyn",
    "step4Feat2Name": "Płaski dysk",
    "step4Feat2Badge": "Tonda Romana",
    "step4Feat3Name": "Styl rzymski",
    "step4Feat3Badge": "Tonda Romana",
    "step4Quote": "W dłoniach czujesz napięcie ciasta. Wałek bezpowrotnie zniszczyłby pęcherzyki powietrza, które tworzyły się przez dwa dni.",
    "step5Tab": "Piec Drewniany 375°C",
    "step5Sci": "Równomierne pieczenie i złocisty chrupiący brzeg",
    "step5Title": "Piec Opalany Drewnem 375 °C: 2–3 minuty chrupiącego pieczenia",
    "step5Desc": "Nasz ceglany piec kopułowy osiąga 375 °C. Tonda Romana piecze się dłużej niż neapolitańska pizza – od 2 do 3 minut – dzięki czemu chrupiący spód staje się złocisty, a środek pozostaje lekki. San Marzano zachowują świeżą kwasowość, mozzarella ładnie się topi, a brzeg jest płaski i chrupiący.",
    "step5CardTitle": "Piec na Drewno",
    "step5CardSub": "Płyta kamienna Biscotto i płomień buka",
    "step5Spec1Label": "Czas Pieczenia",
    "step5Spec1Desc": "Dłuższe pieczenie dla złocistego, chrupiącego spodu",
    "step5Spec2Label": "Rodzaj Drewna",
    "step5Spec2Desc": "Czysty płomień bez żywic dla subtelnej nuty dymnej",
