    "step5Feat2Name": "Złocisty chrupiący spód",
    "step5Feat3Name": "Świeżość dodatków",
    "step5Feat3Badge": "100% soczystości",
    "step5Quote": "Od dwóch do trzech minut w 375 stopniach. Chrupiący spód, który ożywia każdy kęs."
