    "rev1_author": "Matej K.",
    "rev1_date": "před 2 týdny",
    "rev1_text": "Vynikající neapolská pizza v nádherném prostředí Hradu Kodeljevo. Nadýchané okraje, perfektní omáčka ze San Marzana a skvělý personál. Vřele doporučuji!",
    "rev2_author": "Ana P.",
    "rev2_date": "před měsícem",
    "rev2_text": "Nejlepší pizza v Lublani! Atmosféra na terase je kouzelná a sendvič Panuozzo s mortadelou a pistáciemi je naprosto dokonalý.",
    "rev3_author": "Luka M.",
    "rev3_date": "před 3 týdny",
    "rev3_text": "Skvělá atmosféra pod hradem, výborný výběr nápojů a opravdová neapolská pizza na té nejvyšší úrovni. Určitě se brzy vrátíme!",
    "rev4_author": "Elena T.",
    "rev4_date": "před měsícem",
    "rev4_text": "Opravdu výjimečné místo v Lublani. Úžasné těsto na pizzu, skvělý výběr vín a o víkendech perfektní hudební nálada.",
    "rev5_author": "Jan B.",
    "rev5_date": "před 2 měsíci",
    "rev5_text": "Atmosféra 10/10, jídlo a pizza naprosto famózní. Panuozzo Mortadella je opravdový kulinářský zážitek. Skvělá obsluha!",
    "rev6_author": "Katarina S.",
    "rev6_date": "před 3 týdny",
    "rev6_text": "Krásné prostředí, špičková ručně vytahovaná pizza a velmi milá obsluha. Naprostá povinnost pro všechny milovníky pravé pizzy!",
