    "faqPhotoTitle": "Zákaz Fotografování a Natáčení",
    "faqPhotoBadge": "NÁLEPKA NA FOTOAPARÁT",
    "faqPhotoHighlight": "Žádné fotoaparáty na parketu. Prožívejte přítomný okamžik a chraňte soukromí ostatních.",
    "faqPhotoText": "Kader ctí berlínskou tradici svobody na tanečním parketu a diskrétnosti. Při vstupu přelepujeme fotoaparáty telefonů samolepkami. Focení a natáčení v podzemním klubu je přísně zakázáno.",
    "faqDressTitle": "Dress Code",
    "faqDressBadge": "PŘIJĎTE, JAK JSTE",
    "faqDressHighlight": "Přijďte tak, jak se cítíte nejlépe. Černá, kůže, expresivní styl, pohodlí.",
    "faqDressText": "Nemáme rigidní pravidla oblékání, ale vítáme autenticitu, individualitu a respekt ke klubové komunitě. Zvolte oblečení, ve kterém můžete volně protancovat celou noc.",
    "faqAgeTitle": "Věkové Omezení a Fyzický Průkaz (18+)",
    "faqAgeBadge": "PŘÍSNĚ 18+",
    "faqAgeHighlight": "Vstup je povolen pouze dospělým s platným fyzickým dokladem totožnosti.",
    "faqAgeText": "Vstup do nočního klubu Kader je přísně od 18 let. U dveří je nutné předložit platný fyzický doklad s fotografií (občanský průkaz nebo pas). Fotografie v mobilu nejsou akceptovány.",
    "faqSaferTitle": "Bezpečný Prostor a Awareness Tým",
    "faqSaferBadge": "NE ZNAMENÁ NE · TÝM AWARENESS NA MÍSTĚ",
    "faqSaferHighlight": "Nulová tolerance k obtěžování a diskriminaci. Náš tým dohlíží na bezpečí po celou noc.",
    "faqSaferText": "Kader udržuje nekompromisní politiku nulové tolerance vůči jakémukoli obtěžování, diskriminaci, homofobii či překračování osobních hranic. Pokud se necítíte bezpečně, obraťte se na awareness tým, obsluhu nebo ochranku.",
    "faqPaymentTitle": "Platby a Šatna",
    "faqPaymentBadge": "BEZKONTAKTNĚ I HOTOVOST",
    "faqPaymentHighlight": "Přijímáme platební karty, bezkontaktní platby i hotovost. Hlídaná šatna je k dispozici u vstupu.",
    "faqPaymentText": "Na všech barech můžete platit rychle kartou, telefonem i hotovostí. Pro vaše pohodlí doporučujeme využít hlídanou šatnu u vstupu.",
    "faqSoundTitle": "Zvukový Systém Klipsch a Ochrana Sluchu",
    "faqSoundBadge": "ŠPUNTY DO UŠÍ ZDARMA",
    "faqSoundHighlight": "Špičkový hornový systém Klipsch La Scala. Kvalitní špunty do uší zdarma na baru.",
    "faqSoundText": "Srdcem klubu Kader je legendární třípásmový plně hornový systém Klipsch La Scala poháněný studiovými zesilovači. Zvuk je křišťálově čistý a dynamický. Na každém baru nabízíme bezplatné ochranné špunty do uší."
