    "step1Desc": "Základem našeho těsta Tonda Romana je rustikální směs mouky Mulino Caputo typu \"00\" a kamenně mletých obilovin pro plnější, zrnitější střídku. Používáme čerstvý kvásek a uměřené množství vody, aby těsto pomalu zrálo a získalo typicky křupavý charakter.",
