    "step3Title": "48hodinová Řízená Fermentace v Chladu při 4 °C",
    "step3Desc": "Bochánky těsta odpočívají přesně 48 hodin ve specializované chladicí místnosti. Během tohoto pomalého zrání přírodní enzymy (amylázy a proteázy) štěpí složité škroby a lepkové bílkoviny na jednoduché cukry a aminokyseliny. Těsto je tak přirozeně lehce stravitelné — po jídle nikdy neucítíte těžkost v žaludku.",
