    "rev1_author": "Matej K.",
    "rev1_date": "hace 2 semanas",
    "rev1_text": "Excepcional pizza napolitana en el hermoso entorno del Castillo Kodeljevo. Bordes esponjosos, salsa San Marzano exquisita y un trato inmejorable. ¡Muy recomendable!",
    "rev2_author": "Ana P.",
    "rev2_date": "hace 1 mes",
    "rev2_text": "¡La mejor pizza de Liubliana! El ambiente en la terraza del castillo es maravilloso y el Panuozzo de mortadela con pistachos es sencillamente insuperable.",
    "rev3_author": "Luka M.",
    "rev3_date": "hace 3 semanas",
    "rev3_text": "Un ambiente fantástico bajo el castillo, gran carta de bebidas y pizza napolitana al más alto nivel artesanal. ¡Volveremos seguro!",
    "rev4_author": "Elena T.",
    "rev4_date": "hace 1 mes",
    "rev4_text": "Un lugar realmente singular en Liubliana. Masa de pizza impecable, cuidada selección de vinos y una atmósfera vibrante los fines de semana.",
    "rev5_author": "Jan B.",
    "rev5_date": "hace 2 meses",
    "rev5_text": "Ambiente 10/10, comida y pizza deliciosas. El Panuozzo Mortadella es pura gloria. ¡El personal es atentísimo!",
