    "step1Sci": "Estructura del grano y levadura natural",
    "step1Title": "Harina \"00\" Rústica y Levadura Natural",
    "step1Desc": "La base de nuestra masa Tonda Romana es una mezcla rústica de harina Mulino Caputo tipo \"00\" y cereales molidos a la piedra, para una miga más plena y texturizada. Usamos levadura fresca y una cantidad medida de agua para que la masa madure lentamente y desarrolle su característico crujiente.",
    "step1CardTitle": "Harina y Levadura",
    "step1CardSub": "Estructura de grano auténtica napolitana",
