    "step1Spec2Desc": "Equilibrio óptimo entre elasticidad y extensibilidad",
    "step1Feat1Name": "Molienda 100% napolitana",
    "step1Feat2Name": "Bajo contenido en levadura",
    "step1Feat3Name": "Sal marina de Piran",
