    "step1Quote": "Una gran pizza comienza conociendo el grano. Una harina auténtica permite que la masa respire.",
    "step2Tab": "Hidratación Rústica 55 %",
    "step2Sci": "Fijación del agua y estructura de la miga",
    "step2Title": "Masa Rústica de Baja Hidratación",
    "step2Desc": "La Tonda Romana es famosa por su base fina y crujiente. Trabajamos la masa al 55 %–60 % de hidratación – mucho menos que el estilo napolitano – de modo que la corteza queda plana, aireada y crujiente en lugar de alta y esponjosa.",
    "step2CardTitle": "Hidratación de la Masa",
    "step2CardSub": "Baja hidratación para un borde crujiente",
    "step2Spec1Label": "Proporción de Líquido",
    "step2Spec1Desc": "55–60 % de agua para una masa más firme",
    "step2Spec2Label": "Temperatura del Agua",
    "step2Spec2Desc": "Control de fricción durante el amasado lento en espiral",
    "step2Feat1Name": "Amasado lento en espiral",
    "step2Feat1Badge": "20 minutos",
    "step2Feat2Name": "Suavidad de la miga",
    "step2Feat2Badge": "Dorado y plano",
    "step2Feat3Name": "Elasticidad de los alvéolos",
    "step2Feat3Badge": "Impecable",
    "step2Quote": "El agua en la masa es vida. Más agua se traduce en mayor ligereza y menos carbohidratos en cada bocado.",
    "step3Tab": "48h Maduración en Frío",
    "step3Sci": "Maduración y degradación enzimática",
    "step3Title": "48 Horas de Fermentación Lenta Controlada a 4 °C",
    "step3Desc": "Las bolas de masa reposan durante 48 horas exactas en cámara frigorífica. Durante esta lenta maduración, las enzimas naturales (amilasas y proteasas) descomponen los almidones complejos y las proteínas del gluten en azúcares simples y aminoácidos. La masa queda predigerida de forma natural, evitando cualquier sensación de pesadez.",
    "step3CardTitle": "Maduración",
    "step3CardSub": "Evolución enzimática sin prisas",
    "step3Spec1Label": "Temperatura de la Cámara",
    "step3Spec1Desc": "Actividad ralentizada de las levaduras para un desarrollo aromático complejo",
    "step3Spec2Label": "Impacto Glucémico",
    "step3Spec2Desc": "Los almidones complejos ya se encuentran descompuestos",
    "step3Feat1Name": "Desarrollo de ácido láctico",
    "step3Feat1Badge": "Aroma profundo",
    "step3Feat2Name": "Cero hinchazón",
    "step3Feat2Badge": "Digestión ligera",
    "step3Feat3Name": "Aireación natural",
    "step3Feat3Badge": "Alvéolos",
    "step3Quote": "El tiempo es el único ingrediente que no se puede comprar ni acelerar. Tras 48 horas, la masa encuentra su alma.",
    "step4Tab": "Formado Tonda Romana",
    "step4Sci": "Masa fina estirada / laminada",
    "step4Title": "Técnica Tonda Romana: una base plana y crujiente",
    "step4Desc": "Tonda Romana designa un estilo redondo, finamente estirado y más crujiente. Estiramos o enrollamos ligeramente la masa a mano en un disco plano; el centro queda fino y el borde se dora en un lis bajo y regular – el soporte ideal para ricos toppings clásicos napolitanos.",
    "step4CardTitle": "Técnica Artesanal",
    "step4CardSub": "Estilo Tonda Romana",
    "step4Spec1Label": "Grosor del Centro",
    "step4Spec1Desc": "Base fina, plana y crujiente",
    "step4Spec2Label": "Altura del Borde (Cornicione)",
