    "step4Feat2Name": "Disco plano",
    "step4Feat2Badge": "Tonda Romana",
    "step4Feat3Name": "Estilo romano",
    "step4Feat3Badge": "Tonda Romana",
    "step4Quote": "Con las manos sientes la tensión de la masa. Un rodillo destruiría las burbujas de aire que tardaron dos días en formarse.",
    "step5Tab": "Horno de Leña 375 °C",
    "step5Sci": "Horneado uniforme y borde dorado crujiente",
    "step5Title": "Horno de Leña a 375 °C: de 2 a 3 minutos crujientes",
    "step5Desc": "Nuestro horno abovedado de ladrillo alcanza 375 °C. La Tonda Romana se hornea más tiempo que una napolitana – de 2 a 3 minutos – para que la base crujiente se dore mientras el centro permanece ligero. Los San Marzano conservan su fresca acidez, la mozzarella se funde bien y el borde es plano y crujiente.",
    "step5CardTitle": "Horno de Leña",
    "step5CardSub": "Suelo de piedra Biscotto y llama de haya",
    "step5Spec1Label": "Tiempo de Cocción",
